(function(){
  var state = "under";
  var $ = function(id){ return document.getElementById(id); };
  var cards = document.querySelector(".cards");
  var text = {
    under: ["ok", "Allowed", "Allow spends one token and the request reaches the mux. The client sees the normal response."],
    over: ["bad", "429 Too Many Requests", "The bucket is empty. The middleware writes Retry-After and returns; the handler never runs and the store is never locked."]
  };
  function draw(){
    var over = state === "over";
    $("handler").setAttribute("opacity", over ? "0.35" : "1");
    $("toHandler").setAttribute("opacity", over ? "0.2" : "1");
    var back = $("back");
    back.setAttribute("d", over ? "M300,96 V150 H70 V100" : "M530,96 V150 H70 V100");
    back.setAttribute("stroke", over ? "#a8322b" : "#2d6a4f");
    back.setAttribute("marker-end", over ? "url(#arr-bad)" : "url(#arr-ok)");
    var label = $("backLabel");
    label.textContent = over ? "429 · Retry-After: 1" : "200 / 201 from the handler";
    label.setAttribute("fill", over ? "#a8322b" : "#2d6a4f");
    label.setAttribute("x", over ? "185" : "300");
    var t = text[state];
    cards.innerHTML = "";
    var c = document.createElement("div"); c.className = "card " + t[0];
    var h = document.createElement("h4"); h.textContent = t[1];
    var p = document.createElement("p"); p.textContent = t[2];
    c.appendChild(h); c.appendChild(p); cards.appendChild(c);
  }
  Viz.seg(document.querySelector(".seg"), function(v){ state = v; draw(); });
  document.querySelector(".play").addEventListener("click", function(){
    if (Viz.reduced) return;
    var dot = $("dot");
    var pts = state === "over" ? [[70,58],[300,58],[300,150],[70,150],[70,100]] : [[70,58],[300,58],[530,58],[530,150],[70,150],[70,100]];
    var i = 0, f = 0; dot.setAttribute("opacity", "1");
    function frame(){
      var a = pts[i], b = pts[i+1];
      if (!b) { dot.setAttribute("opacity", "0"); return; }
      f += 0.06;
      if (f >= 1) { f = 0; i++; return requestAnimationFrame(frame); }
      dot.setAttribute("cx", a[0] + (b[0]-a[0])*f); dot.setAttribute("cy", a[1] + (b[1]-a[1])*f);
      requestAnimationFrame(frame);
    }
    frame();
  });
  draw();
})();

