	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if ok, _ := l.Allow(key(r)); !ok {
			http.Error(w, "slow down", 429)
			return
		}
		next.ServeHTTP(w, r)
	})
}

