(function(){
  var NS = "http://www.w3.org/2000/svg";
  var RATE = 5, N = 12, burst = 10, shown = N, timer;
  function el(tag, attrs, parent, text){ var e = document.createElementNS(NS, tag); for (var k in attrs) e.setAttribute(k, attrs[k]); if (text != null) e.textContent = text; parent.appendChild(e); return e; }
  // The same arithmetic as Allow(): all requests at t=0, so no refill between them.
  function simulate(b){
    var tokens = b, out = [];
    for (var i = 0; i < N; i++) {
      if (tokens >= 1) { tokens -= 1; out.push({ ok: true, left: tokens }); }
      else out.push({ ok: false, left: tokens, wait: Math.ceil((1 - tokens) / RATE) });
    }
    return out;
  }
  function draw(){
    var res = simulate(burst), g = document.getElementById("reqs");
    g.innerHTML = "";
    var left = burst;
    for (var i = 0; i < N; i++) {
      var r = res[i], x = 120 + (i % 6) * 78, y = 36 + Math.floor(i / 6) * 72;
      var visible = i < shown;
      if (visible) left = r.left;
      el("rect", { x: x, y: y, width: 68, height: 58, rx: 6, fill: !visible ? "#f4f4f2" : r.ok ? "#e3f1e8" : "#f8e1de", stroke: !visible ? "#cfcfc9" : r.ok ? "#2d6a4f" : "#a8322b" }, g);
      el("text", { x: x + 34, y: y + 24, "text-anchor": "middle", fill: "#1a1a1a" }, g, "#" + (i + 1));
      el("text", { x: x + 34, y: y + 45, "text-anchor": "middle", "font-size": 13, fill: !visible ? "#4d4d4d" : r.ok ? "#2d6a4f" : "#a8322b" }, g, !visible ? "…" : r.ok ? "allowed" : "429");
    }
    var h = 136 * (left / burst);
    var level = document.getElementById("level");
    level.setAttribute("height", String(Math.max(0, h)));
    level.setAttribute("y", String(36 + 136 - Math.max(0, h)));
    document.getElementById("tokens").textContent = left.toFixed(0) + " / " + burst;
    var allowed = res.filter(function(r){ return r.ok; }).length;
    var cards = document.querySelector(".cards");
    cards.innerHTML = "";
    [["ok", allowed + " allowed", "A quiet client may send up to the burst at once."],
     ["bad", (N - allowed) + " rejected", "Each gets 429 with Retry-After: 1. The next token arrives in 1/5 s = 200 ms, rounded up to whole seconds."]].forEach(function(c){
      var d = document.createElement("div"); d.className = "card " + c[0];
      var h4 = document.createElement("h4"); h4.textContent = c[1];
      var p = document.createElement("p"); p.textContent = c[2];
      d.appendChild(h4); d.appendChild(p); cards.appendChild(d);
    });
  }
  Viz.seg(document.querySelector(".seg"), function(v){ burst = Number(v); shown = N; clearInterval(timer); draw(); });
  document.querySelector(".play").addEventListener("click", function(){
    clearInterval(timer);
    if (Viz.reduced) { shown = N; return draw(); }
    shown = 0; draw();
    timer = setInterval(function(){ shown++; draw(); if (shown >= N) clearInterval(timer); }, 260);
  });
  draw();
})();

